from pathlib import Path
root=Path('.')
out=root/'.superdesign'/'init'
out.mkdir(parents=True, exist_ok=True)
def read(p): return (root/p).read_text(encoding='utf-8')
sidebar=read(Path('src/client/Sidebar.tsx'))
welcome=read(Path('src/client/WelcomePage.tsx'))
composer=read(Path('src/client/Composer.tsx'))
context=read(Path('src/client/ContextPanel.tsx'))
main=read(Path('src/client/main.tsx'))
style=read(Path('src/client/style.css'))
components=("# Shared UI components\n\nThe client uses React 19 + TypeScript, Lucide React icons, and one vanilla CSS file. There is no third-party component library.\n\n## Sidebar\n- Source: `src/client/Sidebar.tsx`\n- Renders projects, sessions, new chat actions, settings, migration entry, and local status.\n\n```tsx\n"+sidebar+"\n```\n\n## WelcomePage\n- Source: `src/client/WelcomePage.tsx`\n- Renders the empty-state start screen and two launch actions.\n\n```tsx\n"+welcome+"\n```\n\n## Composer\n- Source: `src/client/Composer.tsx`\n- Renders the prompt composer, attachments, mode/model controls, tool menu, and send/stop actions.\n\n```tsx\n"+composer+"\n```\n\n## ContextPanel\n- Source: `src/client/ContextPanel.tsx`\n- Renders project scope, files, tool parameters, and preview controls.\n\n```tsx\n"+context+"\n```\n")
(out/'components.md').write_text(components,encoding='utf-8')
layouts=("# Shared layouts\n\n## App shell and desktop layout\n- Source: `src/client/main.tsx`\n- Single Electron client entry. It renders the sidebar, topbar, chat workspace, right context rail, settings page, modal layers, notifications, and loading state.\n\n```tsx\n"+main+"\n```\n\n## Sidebar layout\n- Source: `src/client/Sidebar.tsx`\n- Persistent left navigation with nested project sessions.\n\n```tsx\n"+sidebar+"\n```\n")
(out/'layouts.md').write_text(layouts,encoding='utf-8')
routes='''# Routes\n\nThis is a single-page Electron application; it does not use React Router or URL routes.\n\n## `/` — main client\n- Entry: `src/client/index.html`\n- Render entry: `src/client/main.tsx`\n- Main states: chat workspace, settings page, loading state, project modal, tool search, delete confirmation.\n- Shared layout: `Sidebar` + topbar + workspace content + optional context rail.\n\n## Chat empty state\n- `WelcomePage` appears when the active timeline has no events.\n\n## Chat timeline\n- `Messages` appears when events exist and composes message bubbles, markdown, task cards, tool calls, and data tables.\n\n## Settings\n- `SettingsPage` replaces the workspace while retaining the shared shell.\n'''
(out/'routes.md').write_text(routes,encoding='utf-8')
theme='''# Theme and design tokens\n\n## Compact token summary\n- Background: `#f7f8fa`; surface: `#ffffff`; secondary surface: `#fbfbfd`; tertiary surface: `#f3f4f7`\n- Text: `#1a1d24`, `#5b6270`, `#8b93a3`, `#b8bec9`\n- Brand: `#5b5bd6`; hover: `#4a4ac2`; soft brand: `#5b5bd60f`; brand border: `#5b5bd640`\n- Semantic: success `#16a34a`; warning `#d97706`; danger `#dc2626`\n- Lines: `#eceef1`, `#e2e5ea`\n- Font: `Inter, Segoe UI, PingFang SC, Microsoft YaHei UI, Microsoft YaHei, sans-serif`\n- Mono: `SF Mono, Cascadia Code, Consolas, monospace`\n- Radius: 6px / 9px / 12px / 16px\n- Motion: 120–320ms cubic-bezier transitions; reduced motion rules are present in the stylesheet.\n\n## Raw CSS source\n- Source: `src/client/style.css`\n\n```css\n'''+style+'''\n```\n'''
(out/'theme.md').write_text(theme,encoding='utf-8')
pages='''# Page dependency tree\n\n## `/` main client\n- `src/client/main.tsx`\n  - `src/client/api.ts`\n  - `src/client/style.css`\n  - `src/client/Sidebar.tsx`\n    - `src/client/types.ts`\n  - `src/client/WelcomePage.tsx`\n  - `src/client/Composer.tsx`\n    - `src/client/Attachments.tsx`\n    - `src/client/ModelSettings.tsx`\n    - `src/client/types.ts`\n  - `src/client/Messages.tsx`\n    - `src/client/MarkdownMessage.tsx`\n    - `src/client/TaskCard.tsx`\n    - `src/client/ToolCallCard.tsx`\n    - `src/client/components/DataTable.tsx`\n  - `src/client/ContextPanel.tsx`\n  - `src/client/island/IslandLayer.tsx`\n    - `src/client/island/ToolIsland.tsx`\n  - `src/client/SettingsPage.tsx`\n  - `src/client/ProjectModal.tsx`\n  - `src/client/ToolSearchModal.tsx`\n  - `src/client/ToolParameterModal.tsx`\n\nThe empty state, shell, and context rail are the most relevant surfaces for a client redesign.\n'''
(out/'pages.md').write_text(pages,encoding='utf-8')
extract='''# Extractable components\n\n## Sidebar\n- Source: `src/client/Sidebar.tsx`\n- Category: layout\n- Description: Persistent project and session navigation with settings and local runtime status.\n- Extractable props: `activeProjectId`, `activeSessionId`, `page`, `projects`, `sessions`\n- Hardcoded: Chinese labels, Lucide icon choices, CSS classes.\n\n## AppShell\n- Source: `src/client/main.tsx`\n- Category: layout\n- Description: Desktop shell with sidebar, topbar, workspace, context rail, and modal layers.\n- Extractable props: `page`, `rightPanelOpen`\n- Hardcoded: layout regions, topbar breadcrumb, notification placement.\n\n## Composer\n- Source: `src/client/Composer.tsx`\n- Category: basic\n- Description: Prompt composer with attachments, tool picker, model controls, and send state.\n- Extractable props: `busy`, `streaming`, `mode`, `sessionModel`, `usageTotal`\n- Hardcoded: action labels, Lucide icon choices, CSS classes.\n\n## WelcomePage\n- Source: `src/client/WelcomePage.tsx`\n- Category: basic\n- Description: Empty-state launch surface for selecting a project or opening a demo.\n- Extractable props: `toolCount`, `legacyToolCount`\n- Hardcoded: welcome copy and action labels.\n\n## ContextPanel\n- Source: `src/client/ContextPanel.tsx`\n- Category: layout\n- Description: Right-side project scope, file browser, and tool parameter channel.\n- Extractable props: project, files, selectedFiles, folder, currentTool, preview\n- Hardcoded: section labels and file interaction copy.\n'''
(out/'extractable-components.md').write_text(extract,encoding='utf-8')
